// Known vectors were generated by xxtea 3.7.0's raw block cipher with
// Wyze's little-endian length word appended, not by this decoder.
const lakeWrappedKey = "M+ixIbUdlzv+97YpQOs+tgA+bQmdGrGxbUN1OWYQcsdNCmKx"
const lakeWrappedSalt = "wN7l0SOF7mUpuuAE0OgLf5Zlvsu8stPZcqeGixCmzbegN6GusBc4dquvvqN7noIU"

func TestUnwrapLakeCredentials(t *testing.T) {
	for _, tc := range []struct{ wrapped, plain string }{
		{lakeWrappedKey, "0123456789abcdef0123456789abcdef"},
		{lakeWrappedSalt, "AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8="},
	} {
		got, err := unwrapLakeKey(tc.wrapped, "abcdefghijklmnop-long-access-token")
		if err != nil || got != tc.plain {
			t.Fatal("Lake credential vector mismatch")
		}
	}
	for _, input := range []string{"", "bad", "AAAA", strings.Repeat("A", 8192), lakeWrappedKey} {
		if _, err := unwrapLakeKey(input, "wrong-token"); err == nil {
			t.Fatal("malformed/wrong-key input accepted")
		}
	}
}

func TestLakeSessionProvisioningAndRedaction(t *testing.T) {
	for _, provider := range []string{"lake", "webrtc"} {
		t.Run(provider, func(t *testing.T) {
			const token = "abcdefghijklmnop-long-access-token"
			var logs bytes.Buffer
			requests := 0
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				requests++
				var payload map[string]interface{}
				if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
					t.Fatal(err)
				}
				body, _ := json.Marshal(payload)
				digest := md5.Sum([]byte(token + "gbJojEBViLklgwyyDikx5ztSvKBXI5oU"))
				signer := hmac.New(md5.New, []byte(hex.EncodeToString(digest[:])))
				signer.Write(body)
				if r.Header.Get("signature2") != hex.EncodeToString(signer.Sum(nil)) || r.Header.Get("Authorization") != token {
					t.Error("incorrect Lake web authentication")
				}
				switch r.URL.Path {
				case "/v4/camera/get-streams":
					device := payload["device_list"].([]interface{})[0].(map[string]interface{})
					if device["device_id"] != "test-camera" || device["provider"] != "lake" {
						t.Error("wrong camera/provider")
					}
					json.NewEncoder(w).Encode(map[string]interface{}{"code": 1, "data": []interface{}{map[string]interface{}{
						"provider": provider, "params": map[string]interface{}{"channel": "test-channel", "encryption_mode": 7,
							"encryption_key": lakeWrappedKey, "encryption_salt": lakeWrappedSalt},
					}}})
				case "/v4/wcsa/create-connection":
					json.NewEncoder(w).Encode(map[string]interface{}{"code": 1, "data": map[string]interface{}{
						"app_id": "test-app", "rtc_token": "private-rtc-token", "uid": payload["uid"],
					}})
				default:
					t.Error("unexpected endpoint")
					http.NotFound(w, r)
				}
			}))
			defer srv.Close()
			c := NewClient(Credentials{}, "test", zerolog.New(&logs).Level(zerolog.TraceLevel))
			c.NewWyzeURL = srv.URL
			c.SetAuth(&AuthState{AccessToken: token, UserID: "private-user", ExpiresAt: time.Now().Add(time.Hour)})
			session, err := c.GetLakeSession(context.Background(), "test-camera", "HL_PAN4")
			if provider == "lake" {
				if err != nil || session.UID <= 0 || session.EncryptionKey != "0123456789abcdef0123456789abcdef" || requests != 2 {
					t.Fatal("valid Lake session was not provisioned")
				}
			} else if err == nil || requests != 1 {
				t.Fatal("non-Lake provider accepted")
			}
			for _, secret := range []string{token, "private-user", "private-rtc-token", lakeWrappedKey, lakeWrappedSalt} {
				if strings.Contains(logs.String(), secret) {
					t.Fatal("Lake session leaked into trace logs")
				}
			}
		})
	}
}

func TestLakeUpstreamErrorIsRedacted(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		json.NewEncoder(w).Encode(map[string]interface{}{"code": 5, "msg": "private-secret", "data": "private-secret"})
	}))
	defer srv.Close()
	c := NewClient(Credentials{}, "test", zerolog.Nop())
	c.NewWyzeURL = srv.URL
	c.SetAuth(&AuthState{AccessToken: "valid-token", ExpiresAt: time.Now().Add(time.Hour)})
	_, err := c.GetLakeSession(context.Background(), "camera", "HL_PAN4")
	if err == nil || strings.Contains(err.Error(), "private-secret") {
		t.Fatal("upstream error was not redacted")
	}
}

func TestLakeTokenRenewal(t *testing.T) {
	requests := 0
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		requests++
		var body map[string]interface{}
		json.NewDecoder(r.Body).Decode(&body)
		if r.URL.Path != "/v4/wcsa/renew-token" || body["uid"] != float64(12345) || body["device_id"] != "test-camera" {
			t.Error("wrong renewal request")
		}
		json.NewEncoder(w).Encode(map[string]interface{}{"code": 1, "data": map[string]interface{}{"rtc_token": "renewed-token"}})
	}))
	defer srv.Close()
	c := NewClient(Credentials{}, "test", zerolog.Nop())
	c.NewWyzeURL = srv.URL
	c.SetAuth(&AuthState{AccessToken: "token", ExpiresAt: time.Now().Add(time.Hour)})
	token, err := c.RenewLakeToken(context.Background(), "test-camera", "HL_PAN4", 12345)
	if err != nil || token != "renewed-token" {
		t.Fatal("token renewal failed")
	}
	for _, uid := range []int{0, -1, 100000} {
		if _, err := c.RenewLakeToken(context.Background(), "test-camera", "HL_PAN4", uid); err == nil {
			t.Fatal("invalid session UID accepted")
		}
	}
	if requests != 1 {
		t.Fatal("invalid renewal reached Wyze")
	}
}

func TestLakeDoesNotForwardCredentialsOnRedirect(t *testing.T) {
	forwarded := false
	destination := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { forwarded = true }))
	defer destination.Close()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, destination.URL, http.StatusTemporaryRedirect)
	}))
	defer srv.Close()
	c := NewClient(Credentials{}, "test", zerolog.Nop())
	c.NewWyzeURL = srv.URL
	c.SetAuth(&AuthState{AccessToken: "private-token", ExpiresAt: time.Now().Add(time.Hour)})
	_, err := c.GetLakeSession(context.Background(), "test-camera", "HL_PAN4")
	if err == nil || forwarded {
		t.Fatal("Lake request followed an authenticated redirect")
	}
}

func TestLakeRequestsDuringAuthReplacement(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var payload map[string]interface{}
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			http.Error(w, "bad request", 400)
			return
		}
		switch r.URL.Path {
		case "/v4/camera/get-streams":
			json.NewEncoder(w).Encode(map[string]interface{}{"code": 1, "data": []interface{}{map[string]interface{}{
				"provider": "lake", "params": map[string]interface{}{"channel": "test-channel", "encryption_mode": 7,
					"encryption_key": lakeWrappedKey, "encryption_salt": lakeWrappedSalt},
			}}})
		case "/v4/wcsa/create-connection":
			json.NewEncoder(w).Encode(map[string]interface{}{"code": 1, "data": map[string]interface{}{
				"app_id": "test-app", "rtc_token": "test-token", "uid": payload["uid"],
			}})
		case "/v4/wcsa/renew-token":
			json.NewEncoder(w).Encode(map[string]interface{}{"code": 1, "data": map[string]interface{}{"rtc_token": "renewed-token"}})
		}
	}))
	defer srv.Close()
	c := NewClient(Credentials{}, "test", zerolog.Nop())
	c.NewWyzeURL = srv.URL
	auth := func() *AuthState {
		return &AuthState{AccessToken: "abcdefghijklmnop-long-access-token", UserID: "test-user", ExpiresAt: time.Now().Add(time.Hour)}
	}
	c.SetAuth(auth())
	var wg sync.WaitGroup
	errors := make(chan error, 40)
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; i < 400; i++ {
			// Authentication refresh/re-login replaces this pointer under reloginMu.
			c.reloginMu.Lock()
			c.auth = auth()
			c.reloginMu.Unlock()
			time.Sleep(time.Microsecond)
		}
	}()
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, err := c.GetLakeSession(context.Background(), "test-camera", "HL_PAN4")
			errors <- err
			_, err = c.RenewLakeToken(context.Background(), "test-camera", "HL_PAN4", 12345)
			errors <- err
		}()
	}
	wg.Wait()
	close(errors)
	for err := range errors {
		if err != nil {
			t.Fatal(err)
		}
	}
}

func TestLakeRenewalRetriesRejectedAuthOnce(t *testing.T) {
	for _, rejectAgain := range []bool{false, true} {
		t.Run(fmt.Sprint(rejectAgain), func(t *testing.T) {
			calls, logins := 0, 0
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.Path == "/api/user/login" {
					logins++
					json.NewEncoder(w).Encode(map[string]interface{}{"code": 1, "data": map[string]interface{}{
						"access_token": "fresh-access", "refresh_token": "fresh-refresh", "user_id": "test-user",
					}})
					return
				}
				calls++
				if calls == 1 || rejectAgain {
					json.NewEncoder(w).Encode(map[string]interface{}{"code": 2001, "msg": "expired"})
					return
				}
				if r.Header.Get("access_token") != "fresh-access" {
					t.Error("retry used stale authentication")
				}
				json.NewEncoder(w).Encode(map[string]interface{}{"code": 1, "data": map[string]interface{}{"rtc_token": "renewed"}})
			}))
			defer srv.Close()
			c := NewClient(Credentials{Email: "test@example.com", Password: "test", APIID: "test", APIKey: "test"}, "test", zerolog.Nop())
			c.AuthURL, c.NewWyzeURL = srv.URL, srv.URL
			c.SetAuth(&AuthState{AccessToken: "stale-access", ExpiresAt: time.Now().Add(time.Hour)})
			_, err := c.RenewLakeToken(context.Background(), "test-camera", "HL_PAN4", 12345)
			if (err != nil) != rejectAgain || calls != 2 || logins != 1 {
				t.Fatal("Lake authentication retry policy failed")
			}
		})
	}
}
